DROP PROCEDURE IF EXISTS add_migration;
DELIMITER ??
CREATE PROCEDURE `add_migration`()
BEGIN
DECLARE v INT DEFAULT 1;
SET v = (SELECT COUNT(*) FROM `migrations` WHERE `id`='20261026200000');
IF v = 0 THEN

ALTER TABLE `bonk_mastery_tree` ADD COLUMN `layout` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 grid of rows, 1 free layout (rows 0-8, gates 0/0/0/5/10/10/15/15/21)';
ALTER TABLE `bonk_mastery` ADD COLUMN `shape` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 square, 1 round, 2 choice, 3 capstone, 4 one-way, 5 free starter' AFTER `excludes`,
  ADD COLUMN `position` FLOAT NOT NULL DEFAULT 0 COMMENT 'free layout: column, 0-4, fractions for one-way nodes' AFTER `shape`,
  ADD COLUMN `parents` VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'free layout: comma-separated bonk_mastery ids; any learned parent opens the node' AFTER `position`;

UPDATE `bonk_mastery_tree` SET `layout` = 1 WHERE `id` IN (801, 802, 803);
DELETE FROM `bonk_mastery` WHERE `class` = 8 AND `id` NOT IN (80101, 80102, 80103, 80104, 80105, 80106, 80107, 80108, 80109, 80110, 80111, 80112, 80113, 80114, 80121, 80122, 80123, 80124, 80125, 80126, 80127, 80128, 80129, 80130, 80201, 80202, 80203, 80204, 80205, 80206, 80207, 80208, 80209, 80210, 80211, 80212, 80213, 80214, 80221, 80222, 80223, 80224, 80225, 80226, 80227, 80228, 80229, 80230, 80231, 80301, 80302, 80303, 80304, 80305, 80306, 80307, 80308, 80309, 80310, 80312, 80313, 80321, 80322, 80323, 80324, 80325, 80326, 80327, 80328, 80329, 80330, 80331, 80332, 80333);

UPDATE `bonk_mastery` SET `tree` = 801, `row` = 8, `column` = 3, `max_rank` = 1, `required_id` = 0, `required_rank` = 0, `excludes` = 0, `shape` = 3, `position` = 2, `parents` = '80128,80129,80130' WHERE `id` = 80110;
UPDATE `bonk_mastery` SET `tree` = 802, `row` = 4, `column` = 3, `max_rank` = 1, `required_id` = 0, `required_rank` = 0, `excludes` = 80207, `shape` = 2, `position` = 2, `parents` = '80204,80208' WHERE `id` = 80206;
UPDATE `bonk_mastery` SET `tree` = 802, `row` = 4, `column` = 3, `max_rank` = 1, `required_id` = 0, `required_rank` = 0, `excludes` = 80206, `shape` = 2, `position` = 2, `parents` = '80204,80208' WHERE `id` = 80207;
UPDATE `bonk_mastery` SET `tree` = 802, `row` = 8, `column` = 3, `max_rank` = 1, `required_id` = 0, `required_rank` = 0, `excludes` = 0, `shape` = 3, `position` = 2, `parents` = '80228,80230,80231' WHERE `id` = 80210;
UPDATE `bonk_mastery` SET `tree` = 803, `row` = 4, `column` = 3, `max_rank` = 1, `required_id` = 0, `required_rank` = 0, `excludes` = 80307, `shape` = 2, `position` = 2, `parents` = '80305,80324' WHERE `id` = 80306;
UPDATE `bonk_mastery` SET `tree` = 803, `row` = 4, `column` = 3, `max_rank` = 1, `required_id` = 0, `required_rank` = 0, `excludes` = 80306, `shape` = 2, `position` = 2, `parents` = '80305,80324' WHERE `id` = 80307;
UPDATE `bonk_mastery` SET `tree` = 803, `row` = 8, `column` = 3, `max_rank` = 1, `required_id` = 0, `required_rank` = 0, `excludes` = 0, `shape` = 3, `position` = 2, `parents` = '80330,80331,80332' WHERE `id` = 80310;

END IF;
END??
DELIMITER ;
CALL add_migration();
DROP PROCEDURE IF EXISTS add_migration;
